// Open-source licences for everything bundled in the app, plus data with its
// own terms. The package list is generated by scripts/build-licenses.mjs.

import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { useMemo, useState } from 'react';
import { FlatList, Linking, Pressable, StyleSheet, Text, View } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { useTheme } from '../context/ThemeContext';
import licenses from '../legal/licenses.json';
import { AppStackParamList } from '../navigation/types';
import { fonts, Palette, radii, spacing, TypeTokens } from '../theme';

type Props = NativeStackScreenProps<AppStackParamList, 'Licenses'>;

type Pkg = { name: string; version: string; licence: string; repo: string | null; textId: string | null };
const PACKAGES = licenses.packages as Pkg[];
const TEXTS = licenses.texts as Record<string, string>;

// Things the app uses that aren't npm packages, and data with its own terms.
const CREDITS: { title: string; body: string; url: string }[] = [
  {
    title: 'Map data © OpenStreetMap contributors',
    body: 'Place names for dropped pins come from OpenStreetMap through Nominatim. The data is available under the Open Database License.',
    url: 'https://www.openstreetmap.org/copyright',
  },
  {
    title: 'Rates By Exchange Rate API',
    body: 'Currency conversions use exchange rates from ExchangeRate-API.',
    url: 'https://www.exchangerate-api.com',
  },
  {
    title: 'Feather icons',
    body: 'Some icons are drawn from the Feather icon set by Cole Bemis, under the MIT License.',
    url: 'https://github.com/feathericons/feather',
  },
  {
    title: 'Figtree typeface',
    body: 'Copyright 2022 The Figtree Project Authors, under the SIL Open Font License 1.1 (full text with the @expo-google-fonts/figtree package below).',
    url: 'https://github.com/erikdkennedy/figtree',
  },
  {
    title: 'Maps',
    body: 'Maps are provided by Apple Maps on iPhone and Google Maps on Android, under their own terms.',
    url: 'https://policies.google.com/terms',
  },
];

// Every package that ships inside the app, with its licence. Generated by
// scripts/build-licenses.mjs.
export default function LicensesScreen(_: Props) {
  const { colors, type } = useTheme();
  const styles = useMemo(() => makeStyles(colors, type), [colors, type]);
  const insets = useSafeAreaInsets();
  const [open, setOpen] = useState<string | null>(null);

  const header = (
    <View>
      <Text style={[type.bodyMuted, { marginBottom: spacing.lg }]}>
        RollCal is built with open-source software and open data. Thank you to everyone who makes
        them. Tap a package to read its licence.
      </Text>
      {CREDITS.map((c) => (
        <Pressable
          key={c.title}
          onPress={() => Linking.openURL(c.url)}
          accessibilityRole="link"
          style={({ pressed }) => [styles.credit, pressed && { opacity: 0.6 }]}
        >
          <Text style={styles.name}>{c.title}</Text>
          <Text style={type.caption}>{c.body}</Text>
        </Pressable>
      ))}
      <Text style={[styles.section, { marginTop: spacing.lg }]}>
        Packages · {PACKAGES.length}
      </Text>
    </View>
  );

  return (
    <FlatList
      style={styles.screen}
      contentContainerStyle={{ padding: spacing.lg, paddingBottom: insets.bottom + spacing.xl }}
      data={PACKAGES}
      keyExtractor={(p) => `${p.name}@${p.version}`}
      ListHeaderComponent={header}
      ItemSeparatorComponent={() => <View style={styles.divider} />}
      initialNumToRender={30}
      renderItem={({ item }) => {
        const key = `${item.name}@${item.version}`;
        const expanded = open === key;
        const text = item.textId ? TEXTS[item.textId] : null;
        return (
          <View>
            <Pressable
              onPress={() => setOpen(expanded ? null : key)}
              accessibilityRole="button"
              accessibilityState={{ expanded }}
              style={({ pressed }) => [styles.row, pressed && { opacity: 0.6 }]}
            >
              <Text style={styles.name}>{item.name}</Text>
              <Text style={type.caption}>
                {item.version} · {item.licence}
              </Text>
            </Pressable>
            {expanded && (
              <View style={styles.textBox}>
                {text ? (
                  <Text style={styles.licence} selectable>
                    {text}
                  </Text>
                ) : (
                  <Text
                    style={[type.caption, { color: colors.accentText }]}
                    onPress={() =>
                      Linking.openURL(`https://spdx.org/licenses/${item.licence.split(' ')[0]}.html`)
                    }
                  >
                    Licensed under {item.licence}. Read the standard licence text.
                  </Text>
                )}
                {item.repo ? (
                  <Text
                    style={[type.caption, { color: colors.accentText, marginTop: spacing.sm }]}
                    onPress={() => item.repo && Linking.openURL(item.repo)}
                  >
                    Project page
                  </Text>
                ) : null}
              </View>
            )}
          </View>
        );
      }}
    />
  );
}

const makeStyles = (c: Palette, t: TypeTokens) =>
  StyleSheet.create({
    screen: { flex: 1, backgroundColor: c.paper },
    section: { ...t.caption, fontSize: 13, color: c.inkMuted, marginBottom: spacing.xs },
    credit: {
      backgroundColor: c.card,
      borderRadius: radii.md,
      borderWidth: StyleSheet.hairlineWidth,
      borderColor: c.line,
      padding: spacing.md,
      marginBottom: spacing.sm,
      gap: 2,
    },
    row: { paddingVertical: spacing.md, gap: 2 },
    name: { ...t.body, fontFamily: fonts.bodySemiBold, color: c.ink },
    divider: { height: StyleSheet.hairlineWidth, backgroundColor: c.line },
    textBox: {
      backgroundColor: c.card,
      borderRadius: radii.sm,
      borderWidth: StyleSheet.hairlineWidth,
      borderColor: c.line,
      padding: spacing.md,
      marginBottom: spacing.md,
    },
    licence: { fontFamily: 'Courier', fontSize: 11, lineHeight: 15, color: c.ink },
  });
